-- =====================================================================
-- 11_seed_menu_sbux.sql — 스타벅스 기준 메뉴 · 별칭 · 옵션 (D-07 4.11 · 8절)
--
-- ★ 생성 파일이다. 손으로 고치지 말고 생성기를 다시 돌린다:
--     python tools/build_sbux_seed.py <스타벅스_메뉴별_옵션정리.xlsx>
--   출처: 스타벅스_메뉴별_옵션정리.xlsx (유일한 출처 — 가격이 있는 메뉴만) · 별칭: sql/seed_src/sbux_alias.csv
--   공개 메뉴 기준 시연 데이터 · 로고 미사용 (PRD 2.4 · R-13)
--
--   기존 스타벅스 시드를 지우고 다시 넣는다. 주문 이력이 참조하는 메뉴는 지울 수 없어 비활성으로 돌린다.
--   사이즈 가격: Tall 기준 Short -800 · Grande +800 · Venti +1,600 (사이즈 열에 있는 것만).
--   base_price 는 기본 사이즈 가격, 다른 사이즈는 차액이 size 옵션 추가금이다(Short 는 음수).
--   옵션 5종만 DB 로 관리한다 — size · ice · shot(+600) · bean(디카페인 +300) ·
--   cup(개인컵 -400). 시럽 · 우유 · 휘핑 등 그 밖의 요청은 기타 요청(custom_request)이다.
--   기준 menu_version = 'mv_20261029' (app/config.py MENU_VERSION 과 같은 값)
-- =====================================================================

-- --------------------------------------------------------------------
-- 0. 기존 스타벅스 시드 정리
--    별칭 · 옵션은 전부 지운다. 메뉴는 이번 시드에 없는 것만 지운다(있는 것은 아래 INSERT 가 덮어쓴다).
--    order_item.menu_id 는 ON DELETE RESTRICT — 주문 이력이 참조하는 메뉴는 지우지 않고 비활성으로 둔다.
-- --------------------------------------------------------------------
DELETE FROM app.menu_alias WHERE brand_id = 'starbucks';
DELETE FROM app.menu_option WHERE brand_id = 'starbucks'
   OR menu_id IN (SELECT menu_id FROM app.menu WHERE brand_id = 'starbucks');
DELETE FROM app.menu m
 WHERE m.brand_id = 'starbucks' AND m.menu_id NOT IN ('sb_003', 'sb_017', 'sb_c9200000005282', 'sb_c9200000006945', 'sb_c9200000000487', 'sb_c9200000005991', 'sb_c9200000006938', 'sb_c9200000003285', 'sb_016', 'sb_c2', 'sb_c9200000006852', 'sb_c106509', 'sb_c9200000006840', 'sb_c9200000002259', 'sb_c9200000002262', 'sb_c9200000006517', 'sb_c128401', 'sb_c9200000006514', 'sb_c128198', 'sb_c30', 'sb_c25', 'sb_c9200000007131', 'sb_004', 'sb_011', 'sb_015', 'sb_c126197', 'sb_c110601', 'sb_c38', 'sb_c9200000006235', 'sb_013', 'sb_c128692', 'sb_c9200000006238', 'sb_006', 'sb_c128695', 'sb_012', 'sb_c9200000006338', 'sb_014', 'sb_c110572', 'sb_c46', 'sb_c128192', 'sb_c9200000005181', 'sb_c9200000005178', 'sb_c110612', 'sb_018', 'sb_c110611', 'sb_c110614', 'sb_c9200000002760', 'sb_c168007', 'sb_002', 'sb_019', 'sb_c9200000002502', 'sb_020', 'sb_c167004', 'sb_021', 'sb_c169001', 'sb_c9200000006963', 'sb_c9200000006466', 'sb_c9200000003763', 'sb_c9200000007097', 'sb_c9200000005168', 'sb_c9200000006937', 'sb_c9200000005983', 'sb_c107051', 'sb_c9200000004567', 'sb_c9200000006556', 'sb_c9200000007158', 'sb_c9200000007184', 'sb_c9200000006555', 'sb_c9200000007178', 'sb_c9200000007181', 'sb_c9200000006412', 'sb_c9200000007324', 'sb_c9200000006415', 'sb_c9200000007327', 'sb_024', 'sb_c9200000007164', 'sb_c135608', 'sb_c9200000007161', 'sb_c4004000000056', 'sb_c4004000000059', 'sb_023', 'sb_c9200000000229', 'sb_c9200000002959', 'sb_c4004000000019', 'sb_c400400000094', 'sb_c4004000000079', 'sb_c4004000000069', 'sb_c4004000000036', 'sb_c9200000000226', 'sb_005', 'sb_c4004000000016', 'sb_c9200000000187', 'sb_c400400000091', 'sb_c4004000000076', 'sb_c4004000000066', 'sb_c9200000005307', 'sb_c9200000005304', 'sb_c9200000000190', 'sb_c9200000004933', 'sb_c9200000004942', 'sb_c9200000004936', 'sb_c9200000002499', 'sb_026', 'sb_c72', 'sb_025', 'sb_c17', 'sb_027', 'sb_c9300000004346', 'sb_c9300000005406', 'sb_c9300000004348', 'sb_c5210008070', 'sb_c5210008061', 'sb_c9300000005405', 'sb_c9300